    out = [row[:] for row in grid]

    # Separate framed tiles are disconnected by zero-valued gutters.
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            if y1 - y0 < 2 or x1 - x0 < 2:
                continue
            components.append((y0, y1, x0, x1, cells))

    if not components:
        return out

    # Find the common frame color, then the common interior/tile color.
    freq = [0] * 10
    for row in grid:
        for value in row:
            if value:
                freq[value] += 1
    frame = max(range(1, 10), key=lambda color: freq[color])

    interior_freq = [0] * 10
    for y0, y1, x0, x1, cells in components:
        for y, x in cells:
            if y0 < y < y1 and x0 < x < x1 and grid[y][x] != frame:
                interior_freq[grid[y][x]] += 1
    base = max(range(1, 10), key=lambda color: interior_freq[color])

    tiles = []
    for y0, y1, x0, x1, cells in components:
        patch = {}
        for y, x in cells:
            color = grid[y][x]
            if color != frame and color != base:
                patch.setdefault(color, set()).add((y - y0, x - x0))
        tiles.append((y0, y1, x0, x1, patch))

